void update_time_red_magic(int second, int minute, int hour, bool mode, bool am, int day, int month, int year, int weekday)
{
#ifdef ENABLE_FACE_RED_MAGIC
    if (!face_red_magic)
    {
        return;
    }
	lv_img_set_src(face_red_magic_30_134849, face_red_magic_dial_img_30_134849_group[(month / 1) % 10]);
	lv_img_set_src(face_red_magic_31_134849, face_red_magic_dial_img_30_134849_group[(month / 10) % 10]);
	lv_img_set_src(face_red_magic_32_134849, face_red_magic_dial_img_30_134849_group[(day / 1) % 10]);
	lv_img_set_src(face_red_magic_33_134849, face_red_magic_dial_img_30_134849_group[(day / 10) % 10]);
	lv_img_set_src(face_red_magic_48_151287, face_red_magic_dial_img_48_151287_group[(hour / 1) % 10]);
	lv_img_set_src(face_red_magic_49_151287, face_red_magic_dial_img_48_151287_group[(hour / 10) % 10]);
	lv_img_set_src(face_red_magic_50_151287, face_red_magic_dial_img_48_151287_group[(minute / 1) % 10]);
	lv_img_set_src(face_red_magic_51_151287, face_red_magic_dial_img_48_151287_group[(minute / 10) % 10]);

#endif
}

