void update_status_red_magic(int battery, bool connection){
#ifdef ENABLE_FACE_RED_MAGIC
    if (!face_red_magic)
    {
        return;
    }
	lv_img_set_src(face_red_magic_2_131494, face_red_magic_dial_img_2_131494_group[(battery / 1) % 10]);
	lv_img_set_src(face_red_magic_3_131494, face_red_magic_dial_img_2_131494_group[(battery / 10) % 10]);
	lv_img_set_src(face_red_magic_4_131494, face_red_magic_dial_img_2_131494_group[(battery / 100) % 10]);
	if (battery < 100)
	{
		lv_obj_add_flag(face_red_magic_4_131494, LV_OBJ_FLAG_HIDDEN);
	} else {
		lv_obj_clear_flag(face_red_magic_4_131494, LV_OBJ_FLAG_HIDDEN);
	}

#endif
}

