void update_all_red_magic(int second, int minute, int hour, bool mode, bool am, int day, int month, int year, int weekday, 
    int temp, int icon, int battery, bool connection, int steps, int distance, int kcal, int bpm, int oxygen)
{
#ifdef ENABLE_FACE_RED_MAGIC
    update_time_red_magic(second, minute, hour, mode, am, day, month, year, weekday);
    update_weather_red_magic(temp, icon);
    update_status_red_magic(battery, connection);
    update_activity_red_magic(steps, distance, kcal);
    update_health_red_magic(bpm, oxygen);
#endif
}

void update_check_red_magic(lv_obj_t *root, int second, int minute, int hour, bool mode, bool am, int day, int month, int year, int weekday, 
    int temp, int icon, int battery, bool connection, int steps, int distance, int kcal, int bpm, int oxygen)
{
#ifdef ENABLE_FACE_RED_MAGIC
    if (root != face_red_magic)
    {
        return;
    }
    update_time_red_magic(second, minute, hour, mode, am, day, month, year, weekday);
    update_weather_red_magic(temp, icon);
    update_status_red_magic(battery, connection);
    update_activity_red_magic(steps, distance, kcal);
    update_health_red_magic(bpm, oxygen);
#endif
}


